function retryFetch(id){
  const b=bookmarks.find(x=>x.id===id); if(!b) return;
  flash('Trying to read the page again…');
  setTimeout(()=>{
    // DEMO: simulate that the page has since become accessible on retry.
    const key=b.url.toLowerCase().replace(/\/+$/,'');
    const idx=UNREADABLE.indexOf(key); if(idx>=0) UNREADABLE.splice(idx,1);
    const meta=autoFill(b.url);
    if(meta.readable!==false){
      if(!b.title || b.title===b.url) b.title=meta.title||b.title;
      if(!b.description) b.description=meta.description;
      b.favicon=meta.favicon; b.preview=meta.preview; b.contentCollected=true;
      flash('Read the page and collected its details.'); render(); jumpTo(b.id);
    } else {
      flash('Still couldn\'t read the page — try again later.');
    }
  }, 500);
}
