// a note needs a "Show more" if it has multiple lines or is long
function noteNeedsClamp(note){ return (note||'').includes('\n') || (note||'').length>140; }

function render(){
  const q=$("#search").value.trim();
  let matched=bookmarks.filter(b=>matches(b,q));
  // sort the WHOLE matched set before paging
  const cmp={ new:(a,b)=>b.createdAt-a.createdAt, old:(a,b)=>a.createdAt-b.createdAt,
    az:(a,b)=>a.title.localeCompare(b.title), za:(a,b)=>b.title.localeCompare(a.title) }[sortBy];
  matched=matched.slice().sort(cmp);
  // count always describes the whole result set, not just what's visible
  $("#count").textContent = matched.length + (matched.length===1?' bookmark':' bookmarks') + (q?' matching "'+q+'"':'');
  const list=$("#list");
  $("#clearSearch").style.display = q ? '' : 'none';
  if(!matched.length){ list.innerHTML='<div class="empty">'
      + (q?'No bookmarks match "'+escapeHtml(q)+'".'
          :'No bookmarks yet — save your first link above.<br><span style="font-size:13px">You\'ll also be able to import your existing browser bookmarks here.</span>')
      + '</div>'; return; }
  const page=matched.slice(0, shownN);
  list.innerHTML = page.map(b =>
    (b.id===editingId ? editFormHtml(b) :
    '<div class="bm" id="bm-'+b.id+'">'
    + '<div class="preview"><img src="'+b.preview+'" alt=""></div>'
    + '<div class="body">'
    + '<div class="titleline"><img class="favicon" src="'+b.favicon+'" alt=""><span class="title">'+escapeHtml(b.title)+'</span>'
    + '<button class="secondary editBtn" data-id="'+b.id+'" style="margin-left:auto;padding:4px 10px;font-size:12px">Edit</button></div>'
    + '<a class="url" href="'+escapeAttr(b.url)+'" target="_blank" rel="noopener">'+escapeHtml(b.url)+'</a>'
    + (b.description?'<div class="desc">'+escapeHtml(b.description)+'</div>':'')
    + (b.contentCollected===false
        ? '<div class="warn" style="margin-top:8px">Page couldn\'t be read — details entered by you, and <b>the page was not preserved</b> (the image is a placeholder). '
          + '<button class="secondary retryBtn" data-id="'+b.id+'" style="padding:3px 9px;font-size:12px;margin-left:4px">Retry now</button></div>'
        : '')
    + (b.note?'<div class="note'+((noteNeedsClamp(b.note)&&!expanded.has(b.id))?' clamped':'')+'">'+formatNote(b.note)+'</div>'
        + (noteNeedsClamp(b.note)?'<button class="showmore" data-id="'+b.id+'">'+(expanded.has(b.id)?'Show less':'Show more')+'</button>':'') :'')
    + ((b.tags&&b.tags.length)?'<div class="tags">'+b.tags.map(t=>'<span class="tag" data-tag="'+escapeAttr(t)+'" title="Filter to this tag">'+escapeHtml(t)+'</span>').join('')+'</div>':'')
    + '</div></div>')
  ).join('');
  // paging footer
  if(matched.length>page.length){
    list.innerHTML += '<div class="showing">Showing '+page.length+' of '+matched.length+'</div>'
      + '<button class="loadmore" id="loadMore">Load more</button>';
  } else if(matched.length>PAGE){
    list.innerHTML += '<div class="showing">Showing all '+matched.length+'</div>';
  }
  const lm=document.getElementById('loadMore');
  if(lm) lm.onclick=()=>{ shownN+=PAGE; render(); };
  list.querySelectorAll('.showmore').forEach(el=>el.onclick=(e)=>{ e.stopPropagation();
    const id=+el.dataset.id; if(expanded.has(id)) expanded.delete(id); else expanded.add(id); render(); });
  list.querySelectorAll('.tag[data-tag]').forEach(el=>el.onclick=()=>{
    $("#search").value = '#'+el.dataset.tag; shownN=PAGE; render();
    window.scrollTo({top:0, behavior:'smooth'});
  });

