// demo: addresses we pretend we cannot read (unreachable / blocked / 404)
const UNREADABLE = ["https://blocked.example/secret-report"];
function autoFill(url){
  const key = url.toLowerCase().replace(/\/+$/,'');
  if (UNREADABLE.includes(key)){
    return { readable:false, title:"", description:"",
             favicon: faviconFor(url), preview: previewFor(url, "") };
  }
  let meta = KNOWN[key];
  if (!meta){
    let host = url; try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){}
    let path = ''; try { path = new URL(url).pathname.replace(/[-/_]+/g,' ').trim(); } catch(e){}
    const guess = (path || host).split(' ').filter(Boolean).slice(0,6)
                   .map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');
    meta = { title: guess ? guess + " — " + host : host, description: "Saved from " + host };
  }
