function noteNeedsClamp(note){ return (note||'').includes('\n') || (note||'').length>140; }

function preservedLineHtml(b){
  const p=b.preserved; if(!p) return '';
  if(p.status==='saved'){
    const when=p.savedAt?new Date(p.savedAt).toLocaleDateString():'';
    const label=p.kind==='pdf'?'Saved PDF':'Saved copy';
    return '<div class="preserved"><span class="okdot"></span>'
      + '<button class="linklike savedCopyBtn" data-id="'+b.id+'">'+label+(when?' · '+when:'')+'</button>'
