function renderBulkBar(matched){
  const bar=$("#bulkBar");
  if(selected.size===0){ bar.style.display='none'; bar.innerHTML=''; return; }
  bar.style.display='';
  const inArch = locationFilter==='archived';
  bar.innerHTML = '<span class="bulkcount">'+selected.size+' selected</span>'
    + (selected.size<matched.length ? '<button class="secondary" id="selAll">Select all '+matched.length+' matching</button>' : '')
    + '<button class="secondary" id="bAddTag">Add tag…</button>'
    + '<button class="secondary" id="bDelTag">Remove tag…</button>'
    + '<button class="secondary" id="bRead">Mark read</button>'
    + '<button class="secondary" id="bUnread">Mark unread</button>'
    + (inArch ? '<button class="secondary" id="bRestore">Restore</button>'
              : '<button class="secondary" id="bArchive">Archive</button>')
    + '<button class="secondary" id="bDelete" style="color:#b91c1c">Delete</button>'
    + '<button class="secondary" id="bClear" style="margin-left:auto">Clear selection</button>';
  const sel=()=>bookmarks.filter(b=>selected.has(b.id));
  const done=(msg)=>{ selected.clear(); flash(msg); render(); };
  const s=(id,fn)=>{ const el=document.getElementById(id); if(el) el.onclick=fn; };
  s('selAll',()=>{ matched.forEach(b=>selected.add(b.id)); render(); });
  s('bClear',()=>{ selected.clear(); render(); });
  s('bRead',()=>{ sel().forEach(b=>b.read=true); done('Marked '+selected.size+' as read.'); });
  s('bUnread',()=>{ sel().forEach(b=>b.read=false); done('Marked '+selected.size+' as unread.'); });
  s('bArchive',()=>{ const n=selected.size; sel().forEach(b=>b.archived=true); done('Archived '+n+' bookmarks.'); });
  s('bRestore',()=>{ const n=selected.size; sel().forEach(b=>b.archived=false); done('Restored '+n+' bookmarks.'); });
  s('bAddTag',()=>{ const t=prompt('Add which tag to the '+selected.size+' selected bookmarks?'); if(!t) return;
    const c=canonTag(t.trim()); sel().forEach(b=>{ if(!(b.tags||[]).some(x=>x.toLowerCase()===c.toLowerCase())) (b.tags=b.tags||[]).push(c); });
    done('Added tag "'+c+'".'); });
  s('bDelTag',()=>{ const t=prompt('Remove which tag from the '+selected.size+' selected bookmarks?'); if(!t) return;
    const lc=t.trim().toLowerCase(); sel().forEach(b=>{ b.tags=(b.tags||[]).filter(x=>x.toLowerCase()!==lc); });
    done('Removed tag "'+t.trim()+'".'); });
  s('bDelete',()=>{ const n=selected.size;
    if(confirm('Permanently delete '+n+' bookmarks?\nThis cannot be undone (and removes their saved copies).')){
      bookmarks=bookmarks.filter(b=>!selected.has(b.id)); done('Permanently deleted '+n+' bookmarks.'); } });
}

