function openTagPicker(mode){
  const count=selected.size; if(!count) return;
  const selBookmarks=()=>bookmarks.filter(b=>selected.has(b.id));
  const candidates = mode==='add' ? allTags()
     : [...new Set(selBookmarks().flatMap(b=>b.tags||[]))].sort();
  const ov=document.createElement('div'); ov.className='overlay';
  ov.innerHTML='<div class="modal">'
    +'<h3 style="margin:0 0 10px;font-size:15px">'+(mode==='add'?'Add tag to ':'Remove tag from ')+count+' bookmark'+(count>1?'s':'')+'</h3>'
    +'<input type="text" id="tpSearch" placeholder="'+(mode==='add'?'Search or type a new tag…':'Search tags on selected…')+'">'
    +'<div id="tpList" class="tplist"></div>'
    +'<div class="row" style="justify-content:flex-end;margin-top:10px"><button class="secondary" id="tpCancel">Cancel</button></div>'
    +'</div>';
  document.body.appendChild(ov);
  const close=()=>ov.remove();
  ov.addEventListener('click',e=>{ if(e.target===ov) close(); });
  document.getElementById('tpCancel').onclick=close;
  const search=document.getElementById('tpSearch'); const listEl=document.getElementById('tpList');
  function apply(tag){
    if(mode==='add'){ const c=canonTag(tag);
      selBookmarks().forEach(b=>{ if(!(b.tags||[]).some(x=>x.toLowerCase()===c.toLowerCase())) (b.tags=b.tags||[]).push(c); });
      flash('Added tag "'+c+'" to '+count+' bookmarks.');
    } else { const lc=tag.toLowerCase();
      selBookmarks().forEach(b=>{ b.tags=(b.tags||[]).filter(x=>x.toLowerCase()!==lc); });
      flash('Removed tag "'+tag+'" from '+count+' bookmarks.');
    }
    selected.clear(); close(); render();
  }
  function draw(){
    const qq=search.value.trim().toLowerCase();
    let cs=candidates.filter(t=> qq==='' || t.toLowerCase().includes(qq));
    let html=cs.map(t=>'<button type="button" class="tpItem" data-t="'+escapeAttr(t)+'">'+escapeHtml(t)+'</button>').join('');
    if(mode==='add' && qq && !candidates.some(t=>t.toLowerCase()===qq)){
      html+='<button type="button" class="tpItem tpnew" data-t="'+escapeAttr(search.value.trim())+'">+ Create new tag: “'+escapeHtml(search.value.trim())+'”</button>';
    }
    if(!html) html='<div class="hint" style="padding:8px">'+(mode==='add'?'No existing tags yet. Type to create one.':'The selected bookmarks have no tags to remove.')+'</div>';
    listEl.innerHTML=html;
    listEl.querySelectorAll('.tpItem').forEach(el=>el.onclick=()=>apply(el.dataset.t));
  }
  search.addEventListener('input',draw); draw(); search.focus();
}

