function renderSavedSearches(){
  const row=$("#savedRow"); if(!row) return;
  if(!savedSearches.length){ row.innerHTML=''; return; }
  row.innerHTML='<span class="hint" style="margin-right:4px">Saved:</span>'
    + savedSearches.map(ss=>'<span class="savedchip"><button class="applySaved" data-id="'+ss.id+'" title="'
      +escapeAttr((ss.query||'(no text)')+' · '+ss.status+' · '+ss.location)+'">'+escapeHtml(ss.name)+'</button>'
      +'<button class="delSaved" data-id="'+ss.id+'" title="Delete saved search">×</button></span>').join('');
  row.querySelectorAll('.applySaved').forEach(el=>el.onclick=()=>{
    const ss=savedSearches.find(x=>x.id===+el.dataset.id); if(!ss) return;
    $("#search").value=ss.query||''; statusFilter=ss.status; locationFilter=ss.location;
    $("#statusFilter").value=ss.status; $("#locationFilter").value=ss.location;
    selected.clear(); shownN=PAGE; render(); flash('Applied saved search "'+ss.name+'".');
  });
  row.querySelectorAll('.delSaved').forEach(el=>el.onclick=()=>{
    const ss=savedSearches.find(x=>x.id===+el.dataset.id); if(!ss) return;
    if(confirm('Delete saved search "'+ss.name+'"? (Your bookmarks are not affected.)')){
      savedSearches=savedSearches.filter(x=>x.id!==ss.id); renderSavedSearches(); }
  });
}
function saveCurrentSearch(){
  const query=$("#search").value.trim();
  if(!query && statusFilter==='all' && locationFilter==='active'){
    flash('Set a search or filter first, then save it.'); return; }
