// ---- Import / Export (Netscape bookmark HTML) ----
const IMPORT_SAMPLE = '<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<DL><p>\n'
  +'  <DT><H3>Reading</H3>\n  <DL><p>\n'
  +'    <DT><A HREF="https://example.org/rust-book" ADD_DATE="1609459200" TAGS="rust,reading">The Rust Programming Language</A>\n'
  +'    <DT><A HREF="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Closures" ADD_DATE="1610000000" TAGS="javascript">Closures - MDN</A>\n'
  +'  </DL><p>\n'
  +'  <DT><H3>Design</H3>\n  <DL><p>\n'
  +'    <DT><A HREF="https://example.org/design-patterns" ADD_DATE="1612137600">Design Patterns Catalogue</A>\n'
  +'  </DL><p>\n'
  +'  <DT><A HREF="https://example.org/uncategorised" ADD_DATE="1614556800" TAGS="misc">An uncategorised link</A>\n'
  +'</DL><p>\n';

function parseNetscape(html){
  const doc=new DOMParser().parseFromString(html,'text/html');
  const out=[];
  function walk(dl, folders){
    // children DT may hold H3 (folder, followed by a DL) or A (bookmark)
    Array.from(dl.children).forEach(dt=>{
      const h3=dt.querySelector(':scope > h3');
      const a=dt.querySelector(':scope > a');
      if(h3){ const sub=dt.querySelector(':scope > dl'); if(sub) walk(sub, folders.concat(h3.textContent.trim())); }
      else if(a){
