    +'<h3 style="margin:0 0 10px;font-size:15px">Preferences</h3>'
    +'<label>Default sort</label><select id="pfSort">'
      +opt('new','Newest first',prefs.sort)+opt('old','Oldest first',prefs.sort)
      +opt('az','Title A–Z',prefs.sort)+opt('za','Title Z–A',prefs.sort)+'</select>'
    +'<label>Number displayed per page</label><select id="pfPage">'
      +opt('10','10',String(prefs.pageSize))+opt('20','20',String(prefs.pageSize))
      +opt('50','50',String(prefs.pageSize))+opt('100','100',String(prefs.pageSize))+'</select>'
    +'<label>Text size</label><select id="pfText">'
      +opt('small','Small',prefs.textSize)+opt('normal','Normal',prefs.textSize)+opt('large','Large',prefs.textSize)+'</select>'
    +'<div class="row" style="justify-content:flex-end;margin-top:14px"><button class="secondary" id="pfCancel">Cancel</button><button id="pfSave">Save</button></div>'
    +'</div>';
  document.body.appendChild(ov);
  const close=()=>ov.remove(); ov.addEventListener('click',e=>{ if(e.target===ov) close(); });
  $("#pfCancel").onclick=close;
  $("#pfSave").onclick=()=>{ prefs.sort=$("#pfSort").value; prefs.pageSize=parseInt($("#pfPage").value,10);
    prefs.textSize=$("#pfText").value; applyPrefs(); close(); render(); flash('Preferences saved.'); };
}

