input.content:
:root { --line:#e2e2e6; --muted:#6b7280; --accent:#2563eb; --warn:#b45309; --warnbg:#fff7ed; }
* { box-sizing: border-box; }
body { font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif; margin: 0; color: #111; background: #f6f7f9; }
header { background:#fff; border-bottom:1px solid var(--line); padding:16px 24px; display:flex; align-items:center; justify-content:space-between; gap:12px; }
header h1 { margin:0; font-size:18px; } header .sub { margin:4px 0 0; color:var(--muted); font-size:13px; }
main { max-width:880px; margin:0 auto; padding:24px; }
.card { background:#fff; border:1px solid var(--line); border-radius:10px; padding:16px; margin-bottom:16px; }
.toolbar { display:flex; gap:8px; align-items:center; justify-content:space-between; flex-wrap:wrap; }
.row { display:flex; gap:8px; } .row.shrink { flex:0 0 auto; }
.muted { color:var(--muted); } .small { font-size:13px; }
input[type=text], input[type=url], textarea, select { width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; background:#fff; }
select { width:auto; }
textarea { resize:vertical; min-height:56px; }
label { display:block; font-size:12px; color:var(--muted); margin:10px 0 4px; }
button { padding:9px 15px; border:0; border-radius:8px; background:var(--accent); color:#fff; font-size:14px; cursor:pointer; white-space:nowrap; }
button.secondary { background:#eef1f5; color:#111; }
.hint { color:var(--muted); font-size:12px; margin-top:6px; }
.warn { background:var(--warnbg); border:1px solid #fed7aa; color:var(--warn); border-radius:8px; padding:12px; font-size:13px; margin-top:10px; }
.flash { background:#ecfdf5; border:1px solid #a7f3d0; color:#065f46; border-radius:8px; padding:10px; font-size:13px; margin-bottom:12px; }
.flash.err { background:#fef2f2; border-color:#fecaca; color:#991b1b; }
.list-head { display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; gap:8px; flex-wrap:wrap; }
.count { color:var(--muted); font-size:13px; }
.listctl { display:flex; align-items:center; gap:8px; flex-wrap:wrap; } .listctl label { margin:0; }
.bm { border:1px solid var(--line); border-radius:10px; padding:14px; margin-bottom:10px; background:#fff; display:flex; gap:12px; cursor:pointer; }
.bm:hover { border-color:#c7d2fe; box-shadow:0 1px 4px rgba(0,0,0,.05); }
.bm.archived-card { opacity:.75; } .bm.selected-card { border-color:#818cf8; box-shadow:0 0 0 2px #c7d2fe inset; }
.bm .preview { width:96px; height:64px; border-radius:8px; flex:0 0 auto; overflow:hidden; border:1px solid var(--line); background:#f3f4f6; }
.bm .preview img { width:100%; height:100%; object-fit:cover; display:block; }
.bm .body { flex:1 1 auto; min-width:0; }
.bm .titleline { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.bm .favicon { width:18px; height:18px; border-radius:4px; flex:0 0 auto; }
.unreadDot { width:8px; height:8px; border-radius:50%; background:var(--accent); flex:0 0 auto; }
.archBadge { background:#f3f4f6; color:#6b7280; font-size:11px; padding:2px 8px; border-radius:999px; border:1px solid var(--line); }
.bm .title { font-weight:600; font-size:15px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
.bm .url { color:var(--accent); font-size:12px; word-break:break-all; text-decoration:none; }
.bm .desc { color:#374151; font-size:13px; margin-top:6px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
.bm .note { font-size:13px; margin-top:8px; background:#f9fafb; border-left:3px solid #d1d5db; padding:8px 10px; }
.bm .note.clamped { max-height:4.2em; overflow:hidden; }
.bm .note p { margin:0 0 6px; } .bm .note ul { margin:4px 0; padding-left:18px; }
.tags { margin-top:8px; display:flex; gap:6px; flex-wrap:wrap; }
.tag { background:#eef2ff; color:#3730a3; font-size:11px; padding:3px 8px; border-radius:999px; }
.bm .tag { cursor:pointer; } .bm .tag:hover { background:#e0e7ff; }
.empty { color:var(--muted); font-size:14px; text-align:center; padding:24px; }
.spinner { color:var(--muted); font-size:13px; }
.highlight { background:#fde68a; }
.showmore, .linklike { background:none; color:var(--accent); padding:4px 0; font-size:12px; text-decoration:underline; }
.preserved { font-size:12px; color:#555; margin-top:8px; display:flex; align-items:center; gap:6px; flex-wrap:wrap; }
.preserved a { color:var(--accent); }
.okdot,.penddot,.faildot { width:8px; height:8px; border-radius:50%; flex:0 0 auto; }
.okdot { background:#16a34a; } .penddot { background:#d97706; } .faildot { background:#9ca3af; }
.cardActions { display:flex; gap:6px; flex-wrap:wrap; margin-left:auto; }
.cardActions button { padding:4px 10px; font-size:12px; }
.selBox { align-self:flex-start; margin-top:4px; }
.suggest { margin-top:6px; display:flex; gap:6px; flex-wrap:wrap; align-items:center; }
.suggest .lbl { color:var(--muted); font-size:12px; }
.suggest button.stag { background:#eef2ff; color:#3730a3; border:1px dashed #c7d2fe; font-size:11px; padding:3px 9px; border-radius:999px; }
.metaprev { display:flex; gap:12px; margin-top:12px; align-items:center; }
.metaprev img.fav { width:20px; height:20px; border-radius:4px; }
.metaprev .pv { width:120px; height:72px; border:1px solid var(--line); border-radius:8px; overflow:hidden; }
.metaprev .pv img { width:100%; height:100%; object-fit:cover; display:block; }
.loadmore { display:block; margin:6px auto 20px; }
.showing { text-align:center; color:var(--muted); font-size:12px; margin-bottom:16px; }
.bulkbar { position:sticky; top:0; z-index:5; background:#eef2ff; border:1px solid #c7d2fe; border-radius:10px; padding:10px 12px; margin-bottom:12px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }
.bulkbar .bulkcount { font-weight:600; font-size:13px; }
.savedrow { display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-top:10px; }
.savedchip { display:inline-flex; align-items:center; background:#eef2ff; border:1px solid #c7d2fe; border-radius:999px; overflow:hidden; }
.savedchip .applySaved { background:none; color:#3730a3; font-size:12px; padding:4px 6px 4px 10px; }
.savedchip .delSaved { background:none; color:#6b7280; font-size:14px; padding:4px 8px 4px 4px; }
.savedchip .delSaved:hover { color:#b91c1c; }
.overlay { position:fixed; inset:0; background:rgba(0,0,0,.35); display:flex; align-items:center; justify-content:center; z-index:50; }
.modal { background:#fff; border-radius:12px; padding:18px; width:min(460px,92vw); box-shadow:0 10px 40px rgba(0,0,0,.2); max-height:90vh; overflow:auto; }
.modal h3 { margin:0 0 10px; font-size:15px; } .modal label { color:var(--muted); }
.tplist { max-height:260px; overflow:auto; margin-top:10px; display:flex; flex-direction:column; gap:4px; }
.tpItem { text-align:left; background:#f3f4f6; color:#111; border-radius:8px; padding:8px 10px; font-size:13px; }
